import msgpack,io,json
print('msgpack',msgpack.__version__,'Unpacker_doc', (msgpack.Unpacker.__doc__ or '')[:3000])
b=open('inputs/chall/unknown.data','rb').read()
def pair_hook(pairs): return ('__map__',pairs)
u=msgpack.Unpacker(io.BytesIO(b),raw=False,strict_map_key=False,object_pairs_hook=pair_hook)
def brief(v,path='root',d=0):
 if d>12:return {'type':type(v).__name__,'depth_cap':True}
 if isinstance(v,tuple) and len(v)==2 and v[0]=='__map__':
  return {'type':'map','n':len(v[1]),'keys':[str(k.decode('utf8','replace') if isinstance(k,bytes) else k)[:80] for k,_ in v[1][:100]],'values':[brief(val,path+'/'+str(key).lower(),d+1) for key,val in v[1][:100] for key in [key]]}
 if isinstance(v,list):return {'type':'array','n':len(v),'items':[brief(x,path+'[]',d+1) for x in v[:100]]}
 if isinstance(v,bytes):return {'type':'bytes','n':len(v)}
 if isinstance(v,str):
  p=path.lower()
  if any(z in p for z in ('private','secret','password','token','key','email','credential')):return {'type':'str','n':len(v),'value':'[suppressed]'}
  if any(z in p for z in ('contact','recipient','name','person','identity','display')):return {'type':'str','n':len(v),'value':v[:100]}
  return {'type':'str','n':len(v),'value':'[suppressed]'}
 if v is None or isinstance(v,(bool,int,float)):return {'type':type(v).__name__,'value':v}
 return {'type':type(v).__name__}
items=[]
try:
 for i,v in enumerate(u):
  items.append({'index':i,'offset_end':u.tell(),'summary':brief(v)})
  if i>=19:break
 print('decoded_items',len(items),'next_offset',u.tell())
 print(json.dumps(items,ensure_ascii=True))
except Exception as e:
 print('stream_error',type(e).__name__,str(e),'offset',u.tell(),'decoded_items',len(items))
 print(json.dumps(items,ensure_ascii=True))
